  const rows = [];
  for(const b of bs.slice().sort((x, y) => x.cy - y.cy)){ const last = rows[rows.length - 1];
    if(last && Math.abs(last.y - b.cy) < D / 2){ last.xs.push(b.cx); last.y += (b.cy - last.y) / last.xs.length; } else rows.push({y: b.cy, xs: [b.cx]}); }
  const diffs = [];
  for(const r of rows){ const xs = r.xs.slice().sort((x, y) => x - y); for(let i = 1; i < xs.length; i++){ const d = xs[i] - xs[i - 1]; if(d > 1.1 * D && d < 1.8 * D) diffs.push(d); } }
  S = diffs.length ? med(diffs) : 1.43 * D; const x0 = Math.min(...bs.map(b => b.cx)); cols = [];
  for(let i = 0; i < 10; i++) if(x0 + i * S < W - D * 0.3) cols.push(x0 + i * S);
