    if(gs / lv.length >= 0.3){ on = true; thr = (pct(sorted, 0.03) + pct(sorted, 0.5)) / 2; }
    else { const p50 = pct(sorted, 0.5), p98 = pct(sorted, 0.98); if(p98 - p50 < 50 || p50 < 35) continue; on = false; thr = (p50 + p98) / 2; }
    // 照片（模糊）里绿圈的边是渐暗的，圈外的暗底会被当成图标的笔画：先量出绿圈实际到哪，只取圈里面的
    let cut = rad * rad;
