    for(const [name, ref] of refs){ if(img.grid && KIND.get(name) !== (ri === 0 ? "core" : "extra")) continue; let a = 0, u = 0; for(let i = 0; i < m.length; i++){ a += m[i] & ref[i]; u += m[i] | ref[i]; } top.push([a / Math.max(1, u), name]); }
